<template><div class="page"><div class="toolbar"><el-input v-model="q.keyword" placeholder="任务名称或编号" @keyup.enter.native="load"/><el-select v-model="q.status" clearable placeholder="任务状态"><el-option v-for="v in states" :key="v" :value="v" :label="v"/></el-select><el-button type="primary" @click="load">查询</el-button><el-button type="success" @click="open">新建任务</el-button></div><el-table :data="rows"><el-table-column prop="taskNo" label="任务编号" width="180"/><el-table-column prop="taskName" label="任务名称"/><el-table-column label="扫描源" min-width="180"><template slot-scope="s"><div>{{s.row.repositoryName}}</div><small v-if="s.row.repositoryFileName" class="success">ZIP：{{s.row.repositoryFileName}}</small></template></el-table-column><el-table-column prop="status" label="状态" width="140"/><el-table-column label="进度" width="170"><template slot-scope="s"><el-progress :percentage="percent(s.row)"/></template></el-table-column><el-table-column prop="issueCount" label="问题数" width="80"/><el-table-column label="操作" width="300"><template slot-scope="s"><el-button size="mini" @click="detail(s.row)">详情</el-button><el-button size="mini" type="success" v-if="hasResult(s.row)" @click="result(s.row)">扫描结果</el-button><el-button size="mini" type="primary" v-if="canRun(s.row)" @click="run(s.row)">执行</el-button><el-button size="mini" type="warning" v-if="['QUEUED','RUNNING'].includes(s.row.status)" @click="cancel(s.row)">取消</el-button></template></el-table-column></el-table><el-pagination class="pager" layout="total,prev,pager,next" :total="total" @current-change="p=>{q.pageNum=p;load()}"/><el-dialog title="新建扫描任务" :visible.sync="visible" width="680px"><el-alert title="扫描源将在任务执行时读取，并按文件类型和排除目录递归扫描" type="info" :closable="false" style="margin-bottom:16px"/><el-form label-width="110px"><el-form-item label="任务名称"><el-input v-model="form.taskName"/></el-form-item><el-form-item label="扫描源"><el-select v-model="form.repositoryId" filterable><el-option v-for="r in repos" :key="r.id" :value="r.id" :label="repositoryLabel(r)"/></el-select></el-form-item><el-form-item label="扫描规则"><el-select v-model="form.ruleIds" multiple filterable><el-option v-for="r in rules" :key="r.id" :value="r.id" :label="r.ruleName"/></el-select></el-form-item><el-form-item label="任务说明"><el-input type="textarea" v-model="form.description"/></el-form-item><el-form-item label="立即执行"><el-switch v-model="form.executeImmediately"/></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">创建</el-button></span></el-dialog><el-dialog title="任务详情" :visible.sync="detailVisible" width="720px"><div v-if="selected" class="detail-grid"><div><label>任务编号</label>{{selected.taskNo}}</div><div><label>状态</label>{{selected.status}}</div><div><label>扫描源</label>{{selected.repositoryName}}</div><div><label>ZIP 文件</label>{{selected.repositoryFileName||'-'}}</div><div><label>开始时间</label>{{selected.startTime||'-'}}</div><div><label>总文件</label>{{selected.totalFiles}}</div><div><label>完成文件</label>{{selected.completedFiles}}</div><div><label>成功/失败</label>{{selected.successFiles}} / {{selected.failedFiles}}</div><div><label>问题数</label>{{selected.issueCount}}</div><div><label>错误信息</label>{{selected.errorMessage||'-'}}</div></div></el-dialog></div></template>
<script>import{taskApi,repoApi,ruleApi}from'../api';export default{name:'TaskView',data:()=>({q:{keyword:'',status:'',pageNum:1,pageSize:20},states:['PENDING','QUEUED','RUNNING','CANCEL_REQUESTED','SUCCESS','PARTIAL_SUCCESS','FAILED','CANCELLED'],rows:[],total:0,visible:false,detailVisible:false,selected:null,repos:[],rules:[],form:{taskName:'',description:'',repositoryId:null,ruleIds:[],executeImmediately:true},timer:null}),created(){this.load();this.timer=setInterval(this.load,4000)},beforeDestroy(){clearInterval(this.timer)},methods:{async load(){const r=await taskApi.page(this.q);this.rows=r.list;this.total=r.total},percent(r){return r.totalFiles?Math.round(r.completedFiles*100/r.totalFiles):0},canRun(r){return r.status==='PENDING'},hasResult(r){return['SUCCESS','PARTIAL_SUCCESS'].includes(r.status)},result(r){this.$router.push({path:'/results',query:{taskNo:r.taskNo}})},repositoryLabel(r){return r.sourceType==='UPLOAD'?`${r.repositoryName}（ZIP：${r.originalFileName}）`:r.repositoryName},async open(){const[a,b]=await Promise.all([repoApi.page({enabled:true,pageSize:100}),ruleApi.page({enabled:true,pageSize:100})]);this.repos=a.list.filter(r=>r.sourceType!=='UPLOAD'||Boolean(r.storageKey));this.rules=b.list;this.form={taskName:'',description:'',repositoryId:null,ruleIds:[],executeImmediately:true};this.visible=true},async save(){if(!this.form.taskName||!this.form.repositoryId||!this.form.ruleIds.length)return this.$message.warning('请填写完整任务信息');await taskApi.create(this.form);this.visible=false;this.load()},async run(r){await taskApi.run(r.id);this.load()},async cancel(r){await taskApi.cancel(r.id);this.load()},async detail(r){this.selected=await taskApi.get(r.id);this.detailVisible=true}}}</script>
